"""恋爱报告生成与 PDF 导出。本模块把「多轮情感咨询对话」整理成一份 Markdown 观察报告，再渲染成可下载的 PDF。整体流程（对应 LangChain 的用法）：1. 从 Redis 会话历史取出最近消息（HumanMessage / AIMessage）；2. 用 ChatOpenAI（见 core.llm）流式或一次性生成 Markdown 报告；3. 用 reportlab 把 Markdown 粗解析成 PDF 段落并写盘；4. 通过 report_id 供 API 下载接口查找文件。注意：这里不做向量检索（RAG），只基于会话文本做总结，属于「有记忆的 LLM 调用」。"""from __future__ import annotations  # 允许在类型注解里引用尚未定义的类型名import re  # 正则：清洗 report_id、压缩消息空白import textwrap  # 长行折行，便于 PDF 排版import uuid  # 生成报告唯一 idfrom dataclasses import dataclass  # 定义不可变报告元数据类 LoveReportfrom datetime import datetime  # 文件名时间戳from pathlib import Path  # 路径操作from typing import Any, Iterable  # Any 用于 reportlab story；Iterable 用于流式 Markdownfrom langchain_core.messages import AIMessage, BaseMessage, HumanMessage  # LangChain 消息类型from reportlab.lib import colors  # PDF 颜色定义from reportlab.lib.pagesizes import A4  # A4 纸张尺寸from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet  # PDF 段落样式from reportlab.lib.units import mm  # 毫米单位，用于页边距from reportlab.pdfbase import pdfmetrics  # PDF 字体注册from reportlab.pdfbase.ttfonts import TTFont  # TrueType 字体加载from reportlab.platypus import Paragraph, SimpleDocTemplate, Spacer  # PDF 排版元素from core.llm import create_llm  # 项目统一的 LLM 工厂from core.settings import PROJECT_ROOT, settings  # 项目根路径与报告输出目录配置# ===== 报告生成用的系统提示：约束模型“只根据会话写、不做诊断、注意安全”=====REPORT_SYSTEM_PROMPT = """你是中文情感咨询报告生成助手。你的任务是基于用户与情感咨询助手最近 20 条会话，生成一份“恋爱关系观察报告”。重要边界：- 只能使用会话中出现的信息，不要编造用户没有说过的经历、身份、关系状态、家庭背景或对方性格。- 不做医学诊断，不判断人格障碍，不给出精神疾病标签。- 不替用户做分手、复合、结婚等重大决定，只帮助用户看清关系模式、风险信号和下一步观察/沟通方向。- 如果会话中出现自伤、他伤、暴力、胁迫、跟踪、威胁、严重控制等高风险内容，必须在报告开头加入“安全提醒”，建议用户优先联系当地紧急服务、可信任亲友或专业机构。- 对不确定的信息使用“可能”“看起来”“从目前对话看”这类谨慎表达。- 报告要具体，不要输出空泛鸡汤。- 报告必须使用第二人称“你”，避免居高临下。- 不要提到“我是模型”“根据提示词”“系统要求”等元信息。"""  # 报告 LLM 的 system 角色：约束内容边界与安全要求# ===== 用户侧模板：把格式化后的会话塞进 {conversation_messages} =====REPORT_USER_TEMPLATE = """请基于以下最近 20 条会话，生成一份恋爱关系观察报告。会话内容：{conversation_messages}报告要求：- 输出 Markdown。- 标题使用：# 恋爱关系观察报告- 固定包含以下章节：  ## 1. 当前关系画像  ## 2. 需要留意的信号  ## 3. 给你的行动建议  ## 4. 温和提醒- 如果信息不足，也必须生成报告，但要明确说明“本报告依据有限”。- 每个判断都尽量对应到会话中用户提到的具体线索。- 不要长篇引用原对话，只能做概括。- 总长度控制在 400 到 650 字之间。"""  # 报告 LLM 的 human 模板：{conversation_messages} 由 format_report_conversation 填充@dataclass(frozen=True)  # 不可变数据类：报告元数据写入后不可修改class LoveReport:  # 已落盘恋爱报告的元数据容器    """一份已落盘的恋爱报告元数据（不可变数据类）。    字段:        report_id: 报告唯一 id，用于下载 URL 与文件名匹配。        filename: PDF 文件名。        path: 本地绝对/相对路径。        markdown: 生成 PDF 前的 Markdown 原文，便于调试或二次导出。    """    report_id: str  # 报告 UUID 十六进制串    filename: str  # 磁盘上的 PDF 文件名    path: Path  # PDF 完整路径    markdown: str  # 生成 PDF 前的 Markdown 原文    @property  # 只读属性：由 report_id 派生下载 API 路径    def download_url(self) -> str:  # 前端可直接请求的下载相对 URL        """前端可直接请求的下载路径（对应 emotion_routes 里的 GET /reports/{id}）。"""        return f"/api/emotion/reports/{self.report_id}"  # REST 下载 API 相对路径def generate_love_report_from_messages(messages: list[BaseMessage]) -> LoveReport:  # 同步版：会话消息 → Markdown → PDF    """【同步版】根据会话消息一次性生成 Markdown，并写成 PDF。    参数:        messages: LangChain 消息列表（通常来自 RedisChatMessageHistory.messages）。    返回:        LoveReport 元数据对象。    异常:        ValueError: 用户有效发言不足两轮时拒绝生成，避免空报告。    """    user_message_count = sum(        1 for message in messages if isinstance(message, HumanMessage) and _message_text(message).strip())  # 统计非空用户消息数    if user_message_count < 2:  # 至少两轮用户发言才有足够素材        raise ValueError("当前对话信息不足，至少需要完成两轮咨询后再生成恋爱报告。")  # 拒绝生成空报告    conversation = format_report_conversation(messages)  # 把消息列表格式化为提示词文本    markdown = generate_report_markdown(conversation)  # 同步调用 LLM 生成完整 Markdown    return create_love_report_from_markdown(markdown)  # Markdown 渲染为 PDF 并返回元数据def stream_report_markdown_from_messages(messages: list[BaseMessage]) -> Iterable[str]:  # 流式版：逐片产出 Markdown 文本    """【流式版】根据会话消息流式产出 Markdown 文本分片。    教学要点（LangChain）：    - `create_llm(streaming=True)` 打开流式；    - `llm.stream([...])` 每次 yield 一个 AIMessageChunk，`.content` 是增量 token；    - 上层 service 会把每个分片包装成 SSE 的 `delta` 事件推给前端。    参数:        messages: 会话消息列表。    产出:        非空的 Markdown 文本片段（str）。    异常:        ValueError: 用户有效发言不足两轮。    """    user_message_count = sum(        1 for message in messages if isinstance(message, HumanMessage) and _message_text(message).strip())  # 统计非空用户消息数    if user_message_count < 2:  # 素材不足        raise ValueError("当前对话信息不足，至少需要完成两轮咨询后再生成恋爱报告。")  # 与同步版相同的校验    conversation = format_report_conversation(messages)  # 格式化会话为提示词输入    # temperature 略低，让报告措辞更稳、少发挥。    llm = create_llm(temperature=0.2, streaming=True)  # 低温度 + 流式，报告更稳定    for chunk in llm.stream(            [                ("system", REPORT_SYSTEM_PROMPT),  # 报告边界与安全约束                ("human", REPORT_USER_TEMPLATE.format(conversation_messages=conversation)),  # 填入格式化后的会话            ]    ):        text = str(chunk.content or "")  # 从流式分片取增量文本        if text:  # 跳过空分片            yield text  # 产出 Markdown 增量片段def create_love_report_from_markdown(markdown: str) -> LoveReport:  # 完整 Markdown → 落盘 PDF → 返回元数据    """把完整 Markdown 渲染成 PDF，并返回 LoveReport 元数据。    步骤：生成 report_id → 拼文件名 → 确保输出目录存在 → 调 render_markdown_pdf 写盘。    """    report_id = uuid.uuid4().hex  # 生成 32 位十六进制报告 id    timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")  # 文件名时间戳，便于人工辨认    filename = f"love-report-{timestamp}-{report_id[:8]}.pdf"  # 文件名含时间戳与 id 前 8 位    output_dir = report_dir()  # 解析报告输出目录    output_dir.mkdir(parents=True, exist_ok=True)  # 目录不存在则递归创建    path = output_dir / filename  # 完整 PDF 路径    render_markdown_pdf(markdown, path)  # 把 Markdown 渲染写入 PDF    return LoveReport(report_id=report_id, filename=filename, path=path, markdown=markdown)  # 返回不可变元数据对象def report_dir() -> Path:  # 解析恋爱报告 PDF 的输出目录    """解析恋爱报告输出目录：相对路径则拼到项目根下。"""    path = settings.emotion_reports_dir  # 从配置读取报告目录    if not path.is_absolute():  # 相对路径时拼到项目根        path = PROJECT_ROOT / path  # 得到绝对路径    return path  # 返回报告存储目录def find_report_file(report_id: str) -> Path | None:  # 按 report_id 在输出目录查找 PDF 文件    """按 report_id 在输出目录中查找对应 PDF。    安全处理：先去掉非十六进制字符，再用 id 前 8 位做 glob 匹配（文件名里就带这段）。    找不到或目录不存在时返回 None，由 API 层转成 404。    """    safe_id = re.sub(r"[^0-9a-fA-F]", "", report_id or "")  # 只保留十六进制字符，防路径注入    if not safe_id:  # 清洗后为空则无法查找        return None    directory = report_dir()  # 报告输出目录    if not directory.exists():  # 目录不存在        return None    # 按修改时间倒序，优先返回最新匹配文件。    matches = sorted(directory.glob(f"*{safe_id[:8]}*.pdf"), key=lambda item: item.stat().st_mtime,                     reverse=True)  # glob 匹配含 id 前 8 位的 PDF    for path in matches:  # 遍历候选文件        if path.is_file() and (safe_id in path.stem or safe_id[:8] in path.stem):  # 二次校验 id 在文件名中            return path  # 返回第一个合法匹配    return None  # 未找到def format_report_conversation(messages: list[BaseMessage]) -> str:  # 把最近消息格式化为报告提示词输入    """把最近最多 20 条消息格式化成「[序号] 角色：内容」文本，塞进报告提示词。    只保留有正文的消息；角色映射：HumanMessage→用户，AIMessage→助手。    """    lines: list[str] = []  # 累积格式化后的各行    for index, message in enumerate(messages[-20:], 1):  # 只取最近 20 条，序号从 1 开始        text = _message_text(message)  # 对消息正文去除空白        if not text:  # 跳过空消息            continue        role = "用户" if isinstance(message, HumanMessage) else "助手" if isinstance(message,                                                                                     AIMessage) else "消息"  # 角色中文标签        lines.append(f"[{index}] {role}：{text}")  # 每一轮对话拼在一起    return "\n".join(lines)  # 所有的对话，按\n分割，拼成大的字符串，多行文本供 REPORT_USER_TEMPLATE 使用def generate_report_markdown(conversation_messages: str) -> str:  # 同步调用 LLM 一次性生成完整 Markdown    """【同步】调用 LLM 一次性生成完整 Markdown 报告正文。    与 stream_report_markdown_from_messages 共用同一套 system/user 提示，只是用 invoke 而非 stream。    """    llm = create_llm(temperature=0.2)  # 低温度同步调用    response = llm.invoke(        [            ("system", REPORT_SYSTEM_PROMPT),  # 报告边界约束            ("human", REPORT_USER_TEMPLATE.format(conversation_messages=conversation_messages)),  # 填入会话文本        ]    )    return str(response.content or "").strip()  # 返回完整 Markdown 字符串def render_markdown_pdf(markdown: str, path: Path,                        title: str = "恋爱关系观察报告") -> None:  # 简化 Markdown → A4 PDF 并写入磁盘    """把简化版 Markdown 渲染为 A4 PDF 并写入 path。    支持的 Markdown 子集（够用即可，不是完整 MD 引擎）：    - `# ` 一级标题    - `## ` 二级标题    - `- ` 无序列表    - 其它行当正文    reportlab 的 Paragraph 使用类 HTML 转义，所以正文要先 escape_pdf_text。    """    # 注册 PDF 正文所用的中文字体（reportlab 默认不含中文）。    font_name = register_chinese_font()  # 在 Windows 字体目录中注册可用中文字体    # 基于默认样式表派生中文标题/正文/列表样式。    styles = getSampleStyleSheet()  # reportlab 内置样式表    # 一级标题样式    styles.add(        ParagraphStyle(            name="CnTitle",  # 样式名            parent=styles["Title"],  # 继承内置 Title 样式            fontName=font_name,  # 使用中文字体            fontSize=20,  # 字号            leading=28,  # 行高            textColor=colors.HexColor("#1c1917"),  # 深灰标题色            spaceAfter=10,  # 段后间距        )    )    # 二级标题样式    styles.add(        ParagraphStyle(            name="CnHeading",  # 样式名            parent=styles["Heading2"],  # 继承 Heading2            fontName=font_name,  # 中文字体            fontSize=13,  # 字号            leading=20,  # 行高            textColor=colors.HexColor("#292524"),  # 正文色系            spaceBefore=10,  # 段前间距            spaceAfter=6,  # 段后间距        )    )    # 正文样式    styles.add(        ParagraphStyle(            name="CnBody",  # 样式名            parent=styles["BodyText"],  # 继承正文样式            fontName=font_name,  # 中文字体            fontSize=10.5,  # 字号            leading=17,  # 行高            textColor=colors.HexColor("#292524"),  # 深灰正文色            spaceAfter=6,  # 段后间距        )    )    # 无序列表样式（左缩进 + 首行悬挂，配合 “• ” 前缀）    styles.add(        ParagraphStyle(            name="CnBullet",  # 样式名            parent=styles["BodyText"],  # 继承正文            fontName=font_name,  # 中文字体            fontSize=10.5,  # 字号            leading=17,  # 行高            leftIndent=14,  # 左缩进            firstLineIndent=-10,  # 首行悬挂缩进，形成项目符号效果            textColor=colors.HexColor("#292524"),  # 列表文字色            spaceAfter=4,  # 列表项间距        )    )    # 把 Markdown 行转成 reportlab 的 Flowable 列表（story）。    story: list[Any] = []  # PDF 内容流：Paragraph、Spacer 等可排版元素    for line in markdown_to_lines(markdown):  # 把 Markdown 拆成适合排版的行        if line.startswith("# "):  # 一级标题行            story.append(Paragraph(escape_pdf_text(line[2:].strip() or title), styles["CnTitle"]))  # 去掉 "# " 前缀后渲染            story.append(Spacer(1, 4))  # 标题后留空        elif line.startswith("## "):  # 二级标题行            story.append(Paragraph(escape_pdf_text(line[3:].strip()), styles["CnHeading"]))  # 去掉 "## " 前缀        elif line.startswith("- "):  # 无序列表行            story.append(Paragraph(f"• {escape_pdf_text(line[2:].strip())}", styles["CnBullet"]))  # 用圆点替代 "- "        else:  # 普通正文行            story.append(Paragraph(escape_pdf_text(line), styles["CnBody"]))  # 按正文样式渲染    # 创建 PDF 文档模板并写入磁盘。    document = SimpleDocTemplate(        str(path),  # 输出文件路径（reportlab 需要字符串）        pagesize=A4,  # A4 纸张        rightMargin=18 * mm,  # 右边距 18mm        leftMargin=18 * mm,  # 左边距        topMargin=18 * mm,  # 上边距        bottomMargin=18 * mm,  # 下边距        title=title,  # PDF 元数据标题    )    document.build(story)  # 把 story 排版并写入 PDF 文件def register_chinese_font() -> str:  # 在 Windows 字体目录注册可用中文字体    """在 Windows 常见字体路径中注册一个可用中文字体，返回字体名。    依次尝试 Noto Sans SC / 黑体 / 宋体；都失败则抛 RuntimeError，    因为没有中文字体时 PDF 会显示方框或乱码。    """    candidates = [        Path(r"C:\Windows\Fonts\NotoSansSC-VF.ttf"),  # Google Noto 简体中文可变字体        Path(r"C:\Windows\Fonts\simhei.ttf"),  # 黑体        Path(r"C:\Windows\Fonts\simsun.ttc"),  # 宋体    ]    for path in candidates:  # 按优先级尝试        if not path.exists():  # 字体文件不存在则跳过            continue        try:            pdfmetrics.registerFont(TTFont("EmotionReportCN", str(path)))  # 注册为 EmotionReportCN 字体族            return "EmotionReportCN"  # 返回注册成功的字体名        except Exception:            continue  # 该字体损坏或不可用时尝试下一个    raise RuntimeError("未找到可用中文字体，无法生成中文 PDF。")  # 全部失败则无法生成中文 PDFdef markdown_to_lines(markdown: str) -> list[str]:  # 把 Markdown 拆成适合 PDF 排版的行列表    """把 Markdown 拆成适合 PDF 排版的行列表。    - 空行丢弃；    - 标题/列表行原样保留；    - 普通长行按约 54 字符折行，避免 Paragraph 过宽难读。    """    lines: list[str] = []  # 输出给 render_markdown_pdf 的行列表    for raw in markdown.splitlines():  # 按原始换行拆分        line = raw.strip()  # 去首尾空白        if not line:  # 跳过空行            continue        if line.startswith(("# ", "## ", "- ")):  # 标题或列表行保持原样            lines.append(line)            continue        lines.extend(textwrap.wrap(line, width=54) or [line])  # 长正文按 54 字符折行    return lines  # 返回排版用行列表def escape_pdf_text(text: str) -> str:  # 转义 reportlab Paragraph 会当 HTML 解析的特殊字符    """转义 reportlab Paragraph 会当 HTML 解析的特殊字符，并把换行变成 <br/>。"""    return (        text.replace("&", "&amp;")  # HTML 实体转义 &        .replace("<", "&lt;")  # 转义 <        .replace(">", "&gt;")  # 转义 >        .replace("\n", "<br/>")  # 换行转 reportlab 换行标签    )def _message_text(message: BaseMessage) -> str:  # 从 LangChain 消息对象提取并压缩纯文本    """从 LangChain BaseMessage 取出纯文本，并压缩多余空白。"""    return re.sub(r"\s+", " ", str(message.content or "")).strip()  # 多空格压成单空格并去首尾空白